import { request, app } from 'express';
import { setupTestDatabase, cleanupTestDatabase } from './test-utils/database';

describe('User API integration tests', () => {
  let app: Express;
  let testDb: TestDatabase;

  beforeAll(async () => {
    testDb = await setupTestDatabase();
    app = request(app);
  });

  afterAll(async () => {
    await cleanupTestDatabase(testDb);
  });

  it('should create user via API', async () => {
    const userData = {
      name: 'Test User',
      email: 'test@example.com'
    };

    const response = await request(app)
      .post('/api/users')
      .send(userData)
      .expect(201);

    const createdUser = await testDb.users.findOne({ where: { email: userData.email } });
    expect(createdUser).toBeTruthy();
    expect(createdUser.name).toBe(userData.name);
  });
});


import { Builder, By } from 'selenium-webdriver';
import { testConfig } from './config/test-config';

describe('User registration E2E tests', () => {
  let driver: Builder;
  const baseUrl = testConfig.baseUrl;

  beforeAll(async () => {
    driver = await new Builder().forBrowser('chrome').build();
  });

  it('should complete user registration flow', async () => {
    await driver.get(baseUrl);

    // Fill registration form
    await driver.findElement(By.name('name')).sendKeys('Test User');
    await driver.findElement(By.name('email')).sendKeys('test@example.com');
    await driver.findElement(By.name('password')).sendKeys('password123');
    await driver.findElement(By.name('confirmPassword')).sendKeys('password123');
    await driver.findElement(By.cssSelector('button[type="submit"]')).click();

    // Verify successful registration
    await driver.wait(until.elementLocated(By.cssSelector('.success-message')), 10000);
    const successMessage = await driver.findElement(By.cssSelector('.success-message'));
    expect(await successMessage.getText()).toContain('Registration successful');
  });
});


import { performance } from 'perf_hooks';
import { testConfig } from './config/performance';

describe('Application performance tests', () => {
  it('should handle expected load within response time limits', async () => {
    const metrics = await performance.sample({
      duration: 30000,
      thresholds: { fcp: 1000, lcp: 500 }
    });

    expect(metrics.fcp).toBeLessThan(1000);
    expect(metrics.lcp).toBeLessThan(500);
  });

  it('should maintain performance under sustained load', async () => {
    const metrics = await performance.sample({
      duration: 60000,
      thresholds: { fcp: 1500, lcp: 800 }
    });

    expect(metrics.fcp).toBeLessThan(1500);
    expect(metrics.lcp).toBeLessThan(800);
  });
});


import { request } from 'supertest';
import app from '../src/app';

describe('Security tests', () => {
  it('should prevent SQL injection in login endpoint', async () => {
    const maliciousPayload = {
      email: "admin'--'; DROP TABLE users; --",
      password: 'anything'
    };

    const response = await request(app)
      .post('/api/auth/login')
      .send(maliciousPayload)
      .expect(400);

    const users = await request(app)
      .get('/api/users')
      .expect(200);

    // Verify no users were deleted
    expect(users.body).toHaveLength(0);
  });

  it('should implement proper input validation', async () => {
    const invalidEmailPayload = {
      email: 'not-an-email',
      password: 'password123'
    };

    const response = await request(app)
      .post('/api/auth/login')
      .send(invalidEmailPayload)
      .expect(400);
    expect(response.body.error).toContain('Invalid email format');
  });
});


export class UserFactory {
  static create(overrides: Partial<User> = {}): User {
    const defaultUser: User = {
      id: '1',
      name: 'Test User',
      email: 'test@example.com',
      password: 'password123',
      role: 'user',
      createdAt: new Date(),
      updatedAt: new Date()
    };

    return { ...defaultUser, ...overrides };
  }

  static createAdminUser(overrides: Partial<User> = {}): User {
    return this.create({ ...overrides, role: 'admin' });
  }

  static createTestUsers(count: number): User[] {
    const users: User[] = [];
    for (let i = 0; i < count; i++) {
      users.push(this.create({
        id: `${i + 1}`,
        name: `Test User ${i + 1}`,
        email: `testuser${i + 1}@example.com`,
        password: 'password123'
      }));
    }
    return users;
  }
}
